import { LAYERS, MODEL_TYPES, MOCK_DATASETS, MOCK_DIMENSIONS, MOCK_PROJECT_SPACES, MOCK_STANDARDS } from "./mock-data.js";
import { addField, createInitialState, getDimensions, getLedgerEntries, getProcess, getWizardTasks, hydrateDemoModel, publishModel, removeField, resetDraft, saveDraft, toggleDimension, validateModel } from "./model-state.js";

const MOCK_PROCESSES = MOCK_PROJECT_SPACES;

const state = createInitialState();
const root = document.querySelector("#app");
const steps = ["项目空间与标准", "字段设计", "粒度与复用", "关系设计", "检查与发布"];
const icons = { grid: "▦", model: "⌘", dimension: "◇", process: "↗", standard: "✦", quality: "✓", arrow: "→", back: "←", plus: "+", check: "✓", warning: "!", lock: "⌑", publish: "↗", relation: "⤢", clock: "◷" };
const icon = (name) => icons[name] || "•";
const esc = (value) => String(value == null ? "" : value).replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;");
const layer = (id) => LAYERS.find((item) => item.id === id) || LAYERS[1];
const type = (id) => MODEL_TYPES.find((item) => item.id === id) || MODEL_TYPES[1];
const project = (id) => MOCK_PROJECT_SPACES.find((item) => item.id === id) || MOCK_PROJECT_SPACES[0];
const process = (id) => project(id);
const dataset = (id) => MOCK_DATASETS.find((item) => item.id === id) || MOCK_DATASETS[0];
const standard = (id) => MOCK_STANDARDS.find((item) => item.id === id);
const fieldStandard = (field) => {
  const item = standard(field.standard) || MOCK_STANDARDS.find((entry) => entry.name === field.standard || entry.code === field.name);
  if (!item) return field.standard;
  const shape = item.type + (item.length !== "-" ? "(" + item.length + (item.precision !== "-" ? "," + item.precision : "") + ")" : "");
  return item.code + " · " + shape;
};
const join = (items) => items.join("");

function toast(message, tone) {
  state.toast = { message: message, tone: tone || "info" };
  render();
  window.clearTimeout(toast.timer);
  toast.timer = window.setTimeout(() => { state.toast = null; render(); }, 2600);
}

function select(label, value, options, field, hint) {
  return "<label class='field-control'><span>" + label + "</span><select data-field='" + field + "'>" + join(options.map((item) => "<option value='" + item.value + "'" + (item.value === value ? " selected" : "") + ">" + item.label + "</option>")) + "</select>" + (hint ? "<small>" + hint + "</small>" : "") + "</label>";
}

function sidebar() {
  const activeProject = project(state.model.projectId);
  const nav = [["overview", "grid", "建模总览"], ["wizard", "model", "新建模型"], ["processes", "process", "项目空间"], ["standards", "standard", "数据标准"], ["dimensions", "dimension", "一致性维度"]];
  return "<aside class='sidebar'><div class='brand'><div class='brand-mark'>D</div><div><div class='brand-name'>DTS <span>MODEL</span></div><div class='brand-caption'>数据建模工作台</div></div></div><div class='workspace-switcher'><span class='workspace-dot'></span><div><small>当前建模工作空间</small><strong>节点计划数据空间</strong></div><span class='chevron'>⌄</span></div><div class='sidebar-section-label'>建模导航</div><nav class='nav-list'>" + join(nav.map((item) => "<button class='nav-item " + (state.view === item[0] || (state.view === "published" && item[0] === "wizard") ? "active" : "") + "' data-action='navigate' data-view='" + item[0] + "'><span class='nav-icon'>" + icon(item[1]) + "</span><span>" + item[2] + "</span>" + (item[0] === "wizard" ? "<span class='nav-badge'>DRAFT</span>" : "") + "</button>")) + "</nav><div class='sidebar-section-label'>项目空间上下文</div><div class='context-tree'><div class='tree-row tree-root'><span>⌄</span><span>◎</span><span>" + esc(activeProject.name) + "</span></div><div class='tree-row tree-child'><span class='tree-line'></span><span>◉</span><span>" + esc(activeProject.domain) + "</span><em>" + activeProject.count + "</em></div><div class='tree-row tree-child selected'><span class='tree-line'></span><span>◈</span><span>DWD 明细层</span></div><div class='tree-row tree-child muted'><span class='tree-line'></span><span>◇</span><span>标准字段</span><em>" + activeProject.standardsReady + "/" + MOCK_STANDARDS.length + "</em></div></div><div class='sidebar-spacer'></div><div class='sidebar-note'><span>✦</span><div><strong>建模有据可依</strong><p>项目先行，标准约束，门禁发布。</p></div></div><div class='user-chip'><div class='avatar'>林</div><div><strong>林峰</strong><small>模型设计师</small></div><span>•••</span></div></aside>";
}

function topbar(title, eyebrow) {
  return "<header class='topbar'><div><div class='eyebrow'>" + (eyebrow || "MODEL CENTER") + "</div><h1>" + title + "</h1></div><div class='topbar-actions'><button class='ghost-button' data-action='help'>? <span>使用帮助</span></button><button class='icon-button' data-action='notifications'>♢<i></i></button><div class='topbar-avatar'>林</div></div></header>";
}

function metric(value, label, tone, detail) {
  return "<div class='metric-card metric-" + tone + "'><div class='metric-top'><span>" + label + "</span><span class='metric-icon'>" + icon(tone === "green" ? "quality" : tone === "orange" ? "publish" : "model") + "</span></div><strong>" + value + "</strong><small>" + detail + "</small></div>";
}

function modelRow(model) {
  const layerInfo = layer(model.layer);
  const typeInfo = type(model.type);
  return "<button class='model-row' data-action='open-model' data-model-id='" + model.id + "'><div class='model-type-mark type-" + model.type + "'>" + icon(model.type === "dimension" ? "dimension" : model.type === "summary" ? "relation" : "model") + "</div><div class='model-row-main'><div><strong>" + esc(model.name) + "</strong><span class='model-code'>" + esc(model.code) + "</span></div><div class='model-meta'><span class='layer-pill layer-" + layerInfo.color + "'>" + model.layer + " · " + layerInfo.label + "</span><span>项目：" + esc(model.projectName || model.processName) + "</span><span>" + typeInfo.label + " · " + model.fieldCount + " 字段</span></div></div><div class='model-row-side'><span class='model-status status-" + model.status + "'>" + (model.status === "published" ? "已发布" : "草稿") + "</span><small>" + model.updatedAt + "</small></div><span class='row-arrow'>" + icon("arrow") + "</span></button>";
}

function overview() {
  const activeProject = project(state.model.projectId);
  const projectModels = state.savedModels.filter((item) => (item.projectId || item.processId) === activeProject.id);
  const published = projectModels.filter((item) => item.status === "published").length;
  const drafts = projectModels.filter((item) => item.status === "draft").length;
  const flow = [["01", "项目空间", "明确业务边界"], ["02", "数据标准", "约束字段契约"], ["03", "粒度与维度", "保证可复用"], ["04", "发布门禁", "形成版本快照"]];
  const ready = activeProject.standardsReady + "/" + MOCK_STANDARDS.length;
  return "<main class='main-content'>" + topbar("数据建模", "MODEL CENTER / OVERVIEW") + "<section class='project-context-panel'><div class='project-context-main'><span class='panel-eyebrow'>PROJECT SPACE / ACTIVE</span><h2>" + esc(activeProject.name) + "</h2><p class='project-context-subtitle'>" + esc(activeProject.domain) + " · " + esc(activeProject.ownerDept) + " · 负责人 " + esc(activeProject.owner) + "</p><p class='project-context-scope'>" + esc(activeProject.scope) + "</p><div class='project-context-meta'><span>状态 · " + activeProject.status + "</span><span>版本 · " + activeProject.version + "</span><span>项目空间就是本次建模业务过程</span></div><div class='project-context-actions'><button class='primary-button' data-action='new-model'>" + icon("plus") + " 在此项目空间建模</button><button class='secondary-button' data-action='navigate' data-view='processes'>切换项目空间</button></div></div><div class='project-context-stats'><div class='project-stat'><small>关联模型</small><strong>" + projectModels.length + "</strong><span>空间内可追踪资产</span></div><div class='project-stat'><small>标准就绪</small><strong>" + ready + "</strong><span>字段契约可引用</span></div><div class='project-stat'><small>已发布</small><strong>" + published + "</strong><span>版本可消费</span></div><div class='project-stat'><small>草稿</small><strong>" + drafts + "</strong><span>待完成门禁</span></div></div></section><section class='metrics-grid'>" + metric(String(projectModels.length).padStart(2, "0"), "模型", "blue", published + " 个已发布 · " + drafts + " 个草稿") + metric(String(MOCK_STANDARDS.length).padStart(2, "0"), "数据标准", "green", ready + " 已在当前空间可引用") + metric("DWD", "默认分层", "orange", "明细事实落在标准化明细层") + metric("4", "发布门禁", "violet", "上下文 · 标准 · 粒度 · 关系") + "</section><section class='content-grid overview-grid'><div class='panel model-list-panel'><div class='panel-heading'><div><span class='panel-eyebrow'>MODEL INVENTORY / " + esc(activeProject.name) + "</span><h3>项目空间模型</h3></div><button class='text-button' data-action='navigate' data-view='wizard'>查看全部 " + icon("arrow") + "</button></div><div class='model-list'>" + join(projectModels.map(modelRow)) + "</div></div><div class='panel flow-panel'><div class='panel-heading'><div><span class='panel-eyebrow'>GOVERNED FLOW</span><h3>建模闭环</h3></div><span class='status-dot live'>LIVE</span></div><div class='flow-steps'>" + join(flow.map((item, index) => "<div class='flow-step'><span class='flow-num'>" + item[0] + "</span><div><strong>" + item[1] + "</strong><small>" + item[2] + "</small></div>" + (index < 3 ? "<span class='flow-arrow'>" + icon("arrow") + "</span>" : "") + "</div>")) + "</div><div class='flow-footnote'><span>" + icon("quality") + "</span><span>当前上下文：<b>" + esc(activeProject.name) + "</b> · " + esc(activeProject.domain) + " · DWD</span></div></div></section><section class='panel insight-panel'><div class='insight-icon'>✦</div><div><span class='panel-eyebrow'>MODEL INSIGHT</span><h3>字段设计必须引用数据标准</h3><p>标准提供名称、类型、长度、精度、非空和默认值；没有标准绑定，模型不能进入发布。</p></div><button class='secondary-button' data-action='navigate' data-view='standards'>查看数据标准 " + icon("arrow") + "</button></section></main>";
}

function stepper() {
  return "<div class='stepper'>" + join(steps.map((label, index) => "<button class='step " + (index === state.step ? "current " : "") + (index < state.step ? "done" : "") + "' data-action='jump-step' data-step='" + index + "'><span class='step-index'>" + (index < state.step ? icon("check") : String(index + 1).padStart(2, "0")) + "</span><span>" + label + "</span></button>" + (index < steps.length - 1 ? "<span class='step-line " + (index < state.step ? "done" : "") + "'></span>" : ""))) + "</div>";
}

function fieldRow(field, index) {
  const typeOptions = ["BIGINT", "VARCHAR(32)", "VARCHAR(128)", "DECIMAL(8,4)", "DATE"];
  const roleOptions = [["key", "主键 / 业务键"], ["attribute", "属性"], ["measure", "度量"], ["partition", "分区字段"]];
  return "<tr data-field-id='" + field.id + "'><td><span class='drag-handle'>⋮⋮</span><span class='field-order'>" + String(index + 1).padStart(2, "0") + "</span></td><td><input data-field-prop='name' value='" + esc(field.name) + "'><small>" + esc(field.label) + "</small></td><td><select data-field-prop='type'>" + join(typeOptions.map((item) => "<option " + (item === field.type ? "selected" : "") + ">" + item + "</option>")) + "</select></td><td><select data-field-prop='role'>" + join(roleOptions.map((item) => "<option value='" + item[0] + "' " + (item[0] === field.role ? "selected" : "") + ">" + item[1] + "</option>")) + "</select></td><td><span class='standard-binding " + (field.standard === "待绑定标准" ? "unbound" : "") + "'>" + (field.standard === "待绑定标准" ? "待绑定" : icon("standard") + " " + esc(fieldStandard(field))) + "</span></td><td><button class='row-icon-button danger' data-action='remove-field' data-field-id='" + field.id + "'>×</button></td></tr>";
}

function header() {
  const copy = ["先确定项目空间（业务过程）与数仓位置，再确认标准字段契约。", "把来源字段翻译成可治理、可复用的模型字段。", "用一行是什么和复用维度，避免重复建设。", "显式表达事实与维度的关联，提前拦截分层越级。", "所有门禁通过后，再生成可追踪的模型版本。"];
  return "<div class='wizard-header'><div><span class='panel-eyebrow'>NEW MODEL / " + String(state.step + 1).padStart(2, "0") + "</span><h2>" + steps[state.step] + "</h2><p>" + copy[state.step] + "</p></div><div class='draft-state'><span class='draft-dot'></span>" + (state.model.savedAt ? "已保存 · " + state.model.savedAt : "未保存草稿") + "</div></div>";
}

function legacyContextStep() {
  const p = getProcess(state);
  const d = dataset(state.model.datasetId);
  return "<div class='step-layout'><div class='step-main'><div class='section-title'><span class='section-index'>01</span><div><h3>模型归属</h3><p>选择已经定义好的业务过程，后续字段和粒度都会带着这份业务语义。</p></div></div><div class='form-grid'>" + select("业务过程", state.model.processId, MOCK_PROCESSES.map((item) => ({ value: item.id, label: item.name + " · " + item.domain })), "processId", "来源于 Sprint-64 业务过程登记") + select("数仓分层", state.model.layer, LAYERS.map((item) => ({ value: item.id, label: item.id + " · " + item.label })), "layer", "当前模型必须落在已登记分层") + select("模型类型", state.model.modelType, MODEL_TYPES.map((item) => ({ value: item.id, label: item.label })), "modelType", type(state.model.modelType).hint) + select("来源数据集", state.model.datasetId, MOCK_DATASETS.map((item) => ({ value: item.id, label: item.label + " · " + item.source })), "datasetId", d.columns + " 个字段 · " + d.freshness + "更新") + "</div><div class='process-context-card'><div class='context-symbol'>" + icon("process") + "</div><div class='context-card-copy'><span class='panel-eyebrow'>BUSINESS PROCESS</span><h4>" + p.name + "</h4><p>" + p.description + "</p><div class='context-tags'><span>" + p.domain + "</span><span>负责人：" + p.owner + "</span><span>" + p.count + " 个关联模型</span></div></div><span class='ready-badge'>" + icon("check") + " 已登记</span></div><div class='section-title section-title-spaced'><span class='section-index'>02</span><div><h3>模型基本信息</h3><p>给模型一个业务人员看得懂、工程人员找得到的身份。</p></div></div><div class='form-grid form-grid-two'><label class='field-control'><span>模型中文名称 <b>*</b></span><input data-field='name' value='" + esc(state.model.name) + "'><small>建议使用“业务过程 + 模型语义”命名</small></label><label class='field-control'><span>模型英文编码 <b>*</b></span><input data-field='code' value='" + esc(state.model.code) + "'><small>小写字母、数字和下划线，4-64 位</small></label><label class='field-control field-span-two'><span>模型说明</span><textarea data-field='description' rows='3'>" + esc(state.model.description) + "</textarea></label></div></div><aside class='step-aside'><div class='aside-card precondition-card'><div class='aside-heading'><span>" + icon("lock") + "</span><div><span class='panel-eyebrow'>PRECONDITIONS</span><h4>前置条件</h4></div></div>" + join([["工作空间已选择", "节点计划数据空间"], ["业务过程已登记", p.name], ["分层依赖有效", state.model.layer + " 不越级"], ["来源数据可用", d.label + " · " + d.quality + " 分"]].map((item) => "<div class='check-row'><span class='check-mark'>" + icon("check") + "</span><div><strong>" + item[0] + "</strong><small>" + item[1] + "</small></div></div>")) + "</div><div class='aside-card'><div class='aside-heading'><span>" + icon("model") + "</span><div><span class='panel-eyebrow'>MODEL TYPE</span><h4>" + type(state.model.modelType).label + "</h4></div></div><p class='aside-description'>" + type(state.model.modelType).hint + "</p><div class='type-preview'><span></span><span></span><span></span></div></div></aside></div>";
}

function contextStep() {
  const p = project(state.model.projectId);
  const d = dataset(state.model.datasetId);
  const boundStandards = state.model.standardBindings || [];
  const standardRows = MOCK_STANDARDS.map((item) => {
    const bound = boundStandards.includes(item.id);
    const shape = item.type + (item.length !== "-" ? "(" + item.length + (item.precision !== "-" ? "," + item.precision : "") + ")" : "");
    return "<div class='standard-row " + (bound ? "ready" : "") + "'><div><strong>" + esc(item.name) + "</strong><code>" + item.code + "</code></div><span>" + shape + "</span><span>" + (item.nullable ? "可空" : "非空") + "</span><span>默认 " + item.defaultValue + (item.unit ? " · " + item.unit : "") + "</span><em>" + (bound ? icon("check") + " 已绑定" : "待绑定") + "</em></div>";
  }).join("");
  return "<div class='step-layout'><div class='step-main'><div class='section-title'><span class='section-index'>01</span><div><h3>项目空间上下文</h3><p>项目空间就是本次建模的业务过程边界，模型、数据集和发布版本都归属于这里。</p></div></div><div class='form-grid'>" + select("项目空间（业务过程）", state.model.projectId, MOCK_PROJECT_SPACES.map((item) => ({ value: item.id, label: item.name + " · " + item.domain })), "projectId", "来源于项目空间管理，先确定业务边界") + select("数仓分层", state.model.layer, LAYERS.map((item) => ({ value: item.id, label: item.id + " · " + item.label })), "layer", "明细事实默认进入 DWD 标准化明细层") + select("模型类型", state.model.modelType, MODEL_TYPES.map((item) => ({ value: item.id, label: item.label })), "modelType", type(state.model.modelType).hint) + select("来源数据集", state.model.datasetId, MOCK_DATASETS.filter((item) => !item.projectId || item.projectId === p.id).map((item) => ({ value: item.id, label: item.label + " · " + item.source })), "datasetId", d.columns + " 个字段 · " + d.freshness + "更新") + "</div><div class='project-detail-card'><div class='context-symbol'>" + icon("process") + "</div><div class='context-card-copy'><span class='panel-eyebrow'>PROJECT SPACE / BUSINESS PROCESS</span><h4>" + esc(p.name) + " · " + esc(p.domain) + "</h4><p>" + esc(p.description) + "</p><div class='context-tags'><span>负责人：" + esc(p.owner) + "</span><span>部门：" + esc(p.ownerDept) + "</span><span>范围：" + esc(p.scope) + "</span><span>版本：" + p.version + "</span></div></div><span class='ready-badge'>" + icon("check") + " 已登记</span></div><div class='section-title section-title-spaced'><span class='section-index'>02</span><div><h3>数据标准准备度</h3><p>字段设计前先确认标准可引用，类型、长度、非空和默认值由标准契约约束。</p></div><span class='standard-count'>" + boundStandards.length + "/" + MOCK_STANDARDS.length + " 已绑定</span></div><div class='standard-readiness'><div class='standard-row standard-header'><span>标准名称 / 编码</span><span>类型规格</span><span>空值</span><span>默认值</span><span>状态</span></div>" + standardRows + "</div><div class='section-title section-title-spaced'><span class='section-index'>03</span><div><h3>模型基本信息</h3><p>给模型一个业务人员看得懂、工程人员找得到的身份。</p></div></div><div class='form-grid form-grid-two'><label class='field-control'><span>模型中文名称 <b>*</b></span><input data-field='name' value='" + esc(state.model.name) + "'><small>建议使用“项目空间 + 业务语义”命名</small></label><label class='field-control'><span>模型英文编码 <b>*</b></span><input data-field='code' value='" + esc(state.model.code) + "'><small>小写字母、数字和下划线，4-64 位</small></label><label class='field-control field-span-two'><span>模型说明</span><textarea data-field='description' rows='3'>" + esc(state.model.description) + "</textarea></label></div></div><aside class='step-aside'><div class='aside-card precondition-card'><div class='aside-heading'><span>" + icon("lock") + "</span><div><span class='panel-eyebrow'>PRECONDITIONS</span><h4>前置条件</h4></div></div>" + join([["项目空间已选择", p.name + " · " + p.domain], ["数据标准可引用", boundStandards.length + "/" + MOCK_STANDARDS.length + " 已绑定"], ["分层依赖有效", state.model.layer + " 不越级"], ["来源数据可用", d.label + " · " + d.quality + " 分"]].map((item) => "<div class='check-row'><span class='check-mark'>" + icon("check") + "</span><div><strong>" + item[0] + "</strong><small>" + item[1] + "</small></div></div>")) + "</div><div class='aside-card'><div class='aside-heading'><span>" + icon("model") + "</span><div><span class='panel-eyebrow'>MODEL TYPE</span><h4>" + type(state.model.modelType).label + "</h4></div></div><p class='aside-description'>" + type(state.model.modelType).hint + "</p><div class='type-preview'><span></span><span></span><span></span></div></div></aside></div>";
}

function legacySchemaStep() {
  const d = dataset(state.model.datasetId);
  const keyCount = state.model.fields.filter((item) => item.role === "key").length;
  const measureCount = state.model.fields.filter((item) => item.role === "measure").length;
  return "<div class='step-layout'><div class='step-main'><div class='section-title'><span class='section-index'>01</span><div><h3>字段设计</h3><p>来源：" + d.label + " · " + d.source + "。把数据集字段转换成统一模型语义。</p></div><button class='secondary-button compact' data-action='add-field'>" + icon("plus") + " 添加字段</button></div><div class='table-shell'><table class='field-table'><thead><tr><th>#</th><th>字段名 <span>业务标签</span></th><th>数据类型</th><th>语义角色</th><th>数据标准</th><th></th></tr></thead><tbody>" + join(state.model.fields.map(fieldRow)) + "</tbody></table></div><div class='table-footer'>已配置 <b>" + state.model.fields.length + "</b> 个字段 · 来源数据集共 " + d.columns + " 个字段<button class='text-button' data-action='auto-fill'>自动补齐标准字段 " + icon("arrow") + "</button></div><div class='section-title section-title-spaced'><span class='section-index'>02</span><div><h3>字段治理提醒</h3><p>这里不只是把字段搬过来，而是明确每个字段能不能被复用。</p></div></div><div class='governance-cards'><div class='governance-card positive'><span>" + icon("standard") + "</span><div><strong>5 个字段已绑定标准</strong><p>项目ID、节点ID、版本号等字段将沿用统一命名和类型。</p></div></div><div class='governance-card warning'><span>" + icon("warning") + "</span><div><strong>1 个字段需要确认</strong><p>complete_rate 建议绑定“百分比”度量单位，避免跨模型口径漂移。</p></div><button class='link-button' data-action='bind-standard'>去处理</button></div></div></div><aside class='step-aside'><div class='aside-card schema-summary'><div class='aside-heading'><span>" + icon("model") + "</span><div><span class='panel-eyebrow'>SCHEMA SNAPSHOT</span><h4>字段画像</h4></div></div><div class='schema-stats'><b>" + keyCount + "<small>业务键</small></b><b>" + measureCount + "<small>度量</small></b><b>" + state.model.fields.length + "<small>字段</small></b></div></div><div class='aside-card tip-card'><span class='tip-badge'>TIP</span><h4>字段命名建议</h4><p>优先使用登记的数据标准；没有标准时，用业务人员能理解的英文缩写。</p></div></aside></div>";
}

function schemaStep() {
  const d = dataset(state.model.datasetId);
  const keyCount = state.model.fields.filter((item) => item.role === "key").length;
  const measureCount = state.model.fields.filter((item) => item.role === "measure").length;
  const boundCount = state.model.fields.filter((item) => item.standard && item.standard !== "待绑定标准").length;
  const unboundCount = state.model.fields.length - boundCount;
  return "<div class='step-layout'><div class='step-main'><div class='section-title'><span class='section-index'>01</span><div><h3>字段设计</h3><p>来源：" + d.label + " · " + d.source + "。每个字段都应映射到项目空间可引用的数据标准。</p></div><button class='secondary-button compact' data-action='add-field'>" + icon("plus") + " 添加字段</button></div><div class='table-shell'><table class='field-table'><thead><tr><th>#</th><th>字段名 <span>业务标签</span></th><th>数据类型</th><th>语义角色</th><th>标准契约</th><th></th></tr></thead><tbody>" + join(state.model.fields.map(fieldRow)) + "</tbody></table></div><div class='table-footer'>已配置 <b>" + state.model.fields.length + "</b> 个字段 · 来源数据集共 " + d.columns + " 个字段<button class='text-button' data-action='auto-fill'>自动补齐标准字段 " + icon("arrow") + "</button></div><div class='section-title section-title-spaced'><span class='section-index'>02</span><div><h3>字段治理状态</h3><p>类型、长度、精度、非空和默认值来自标准契约，避免同名字段口径漂移。</p></div></div><div class='governance-cards'><div class='governance-card positive'><span>" + icon("standard") + "</span><div><strong>" + boundCount + " 个字段已绑定标准</strong><p>绑定后沿用标准名称和类型规格，后续模型可直接复用。</p></div></div><div class='governance-card " + (unboundCount ? "warning" : "positive") + "'><span>" + (unboundCount ? icon("warning") : icon("check")) + "</span><div><strong>" + unboundCount + " 个字段待确认</strong><p>未绑定标准的字段不能通过发布门禁。</p></div>" + (unboundCount ? "<button class='link-button' data-action='bind-standard'>去处理</button>" : "") + "</div></div></div><aside class='step-aside'><div class='aside-card schema-summary'><div class='aside-heading'><span>" + icon("model") + "</span><div><span class='panel-eyebrow'>SCHEMA SNAPSHOT</span><h4>字段画像</h4></div></div><div class='schema-stats'><b>" + keyCount + "<small>业务键</small></b><b>" + measureCount + "<small>度量</small></b><b>" + state.model.fields.length + "<small>字段</small></b></div></div><div class='aside-card tip-card'><span class='tip-badge'>STANDARD</span><h4>标准优先</h4><p>字段名、类型、长度和空值规则从数据标准继承；标准变更时，模型可以被统一评估。</p></div></aside></div>";
}

function dimensionCard(item) {
  const selected = state.model.dimensions.includes(item.id);
  const sameDomain = item.domain === project(state.model.projectId).domain;
  return "<button class='dimension-card " + (selected ? "selected" : "") + "' data-action='toggle-dimension' data-dimension-id='" + item.id + "'><div class='dimension-card-top'><span class='dimension-symbol'>" + icon("dimension") + "</span><span class='dimension-match'>" + (sameDomain ? "同数据域" : "公共维度") + "</span>" + (selected ? "<span class='dimension-selected'>" + icon("check") + "</span>" : "") + "</div><strong>" + item.name + "</strong><code>" + item.sourceModel + "</code><div class='dimension-card-meta'><span>键：" + item.keys.join(" / ") + "</span><span>" + item.attributes + " 属性</span></div><div class='dimension-card-action'>" + (selected ? "已加入当前模型" : "+ 复用此维度") + "</div></button>";
}

function grainStep() {
  const keys = state.model.fields.filter((item) => item.role === "key" || item.role === "partition");
  return "<div class='step-layout'><div class='step-main'><div class='section-title'><span class='section-index'>01</span><div><h3>一行代表什么？</h3><p>粒度是事实模型的合同。没有粒度，就无法判断字段是否重复、指标是否可加。</p></div></div><label class='field-control grain-control'><span>粒度声明 <b>*</b></span><textarea data-field='grainStatement' rows='3'>" + esc(state.model.grainStatement) + "</textarea><small>请用业务语言描述，不要只写“明细数据”。</small></label><div class='grain-keys'><div class='inline-heading'><div><h4>粒度键</h4><p>选择共同决定一行唯一性的字段</p></div><span class='key-count'>" + state.model.grainKeys.length + " 个已选</span></div><div class='key-options'>" + join(keys.map((item) => "<label class='key-option " + (state.model.grainKeys.includes(item.name) ? "selected" : "") + "'><input type='checkbox' data-grain-key='" + item.name + "' " + (state.model.grainKeys.includes(item.name) ? "checked" : "") + "><span class='key-check'>" + icon("check") + "</span><span><strong>" + item.name + "</strong><small>" + item.label + " · " + item.type + "</small></span></label>")) + "</div></div><div class='section-title section-title-spaced'><span class='section-index'>02</span><div><h3>优先复用在册维度</h3><p>勾选后，模型关系会自动带入下一步。</p></div><span class='recommendation-label'>RECOMMENDED</span></div><div class='dimension-grid'>" + join(MOCK_DIMENSIONS.map(dimensionCard)) + "</div></div><aside class='step-aside'><div class='aside-card grain-card'><div class='aside-heading'><span>" + icon("relation") + "</span><div><span class='panel-eyebrow'>GRAIN PREVIEW</span><h4>粒度预览</h4></div></div><div class='grain-equation'><span>1 row</span><b>=</b><span class='grain-chip'>项目</span><span>+</span><span class='grain-chip'>节点</span><span>+</span><span class='grain-chip'>版本</span></div><p>" + (state.model.grainStatement ? esc(state.model.grainStatement) : "还没有粒度声明") + "</p><div class='aside-score " + (state.model.grainKeys.length && state.model.grainStatement ? "score-good" : "score-warn") + "'><span>" + (state.model.grainKeys.length && state.model.grainStatement ? icon("check") : icon("warning")) + "</span><div><strong>" + (state.model.grainKeys.length && state.model.grainStatement ? "粒度已具备发布条件" : "还需要补充粒度") + "</strong><small>" + state.model.grainKeys.length + " 个粒度键 · " + getDimensions(state).length + " 个复用维度</small></div></div></div><div class='aside-card duplicate-card'><span class='tip-badge'>GOVERNANCE</span><h4>重复建设提醒</h4><p>项目维度已在公共维度层登记，直接新建同名维度会触发重复建设警告。</p><button class='text-button' data-action='navigate' data-view='dimensions'>查看维度登记 " + icon("arrow") + "</button></div></aside></div>";
}

function relationStep() {
  const dimensions = getDimensions(state);
  return "<div class='step-layout'><div class='step-main'><div class='section-title'><span class='section-index'>01</span><div><h3>模型关系</h3><p>把当前明细事实与公共维度显式连起来，发布时生成可追踪关系。</p></div><button class='secondary-button compact' data-action='add-relation'>" + icon("plus") + " 添加关系</button></div><div class='relation-canvas'><div class='relation-node fact-node'><span class='node-kicker'>FACT / " + state.model.layer + "</span><strong>" + esc(state.model.name || "未命名模型") + "</strong><small>" + state.model.fields.length + " 字段 · " + state.model.grainKeys.length + " 粒度键</small></div><div class='relation-lines'>" + join(state.model.relations.map((item) => "<div class='relation-line'><span></span><em>N:1</em><b>" + icon("arrow") + "</b></div>")) + "</div><div class='dimension-stack'>" + (dimensions.length ? join(dimensions.map((item, index) => { const relation = state.model.relations.find((entry) => entry.targetId === item.id); return "<div class='relation-node dimension-node'><span class='node-kicker'>DIM / " + (index + 1) + "</span><strong>" + item.name + "</strong><small>" + item.sourceModel + " · " + (relation ? relation.on : "待配置") + "</small><span class='relation-valid'>" + icon("check") + " 已校验</span></div>"; })) : "<div class='empty-relation'>还没有复用维度，请返回上一步选择一个维度。</div>") + "</div></div><div class='relation-table-shell'><div class='inline-heading'><div><h4>关系明细</h4><p>当前关系会作为模型发布前的校验输入。</p></div><span class='status-dot live'>" + state.model.relations.length + " RELATIONS</span></div><table class='relation-table'><thead><tr><th>目标模型</th><th>关系类型</th><th>关联条件</th><th>门禁</th></tr></thead><tbody>" + join(state.model.relations.map((item) => "<tr><td><strong>" + item.targetModel + "</strong></td><td><span class='relation-type'>" + item.type + "</span></td><td><code>" + item.on + "</code></td><td><span class='inline-status success'>" + icon("check") + " 通过</span></td></tr>")) + "</tbody></table></div></div><aside class='step-aside'><div class='aside-card rule-card'><div class='aside-heading'><span>" + icon("quality") + "</span><div><span class='panel-eyebrow'>LAYER GUARD</span><h4>分层依赖红线</h4></div></div><div class='rule-route'><span class='layer-pill layer-cyan'>" + state.model.layer + "</span><span>→</span><span class='layer-pill layer-green'>DIM</span></div><p>当前路径符合公共维度依赖方向，不允许从 ADS 直接读取 ODS。</p><div class='aside-score score-good'><span>" + icon("check") + "</span><div><strong>依赖方向有效</strong><small>0 个越级依赖</small></div></div></div><div class='aside-card relation-note'><span class='tip-badge'>NEXT</span><h4>发布后会发生什么？</h4><ul><li>生成模型版本与发布日志</li><li>记录事实-维度关系快照</li><li>同步到模型列表和质量规则入口</li></ul></div></aside></div>";
}

function checkRow(item) {
  return "<div class='validation-row " + (item.passed ? "passed" : item.blocking ? "blocked" : "warning") + "'><span class='validation-icon'>" + (item.passed ? icon("check") : item.blocking ? icon("lock") : icon("warning")) + "</span><div><strong>" + item.label + "</strong><small>" + item.detail + "</small></div><span class='validation-state'>" + (item.passed ? "通过" : item.blocking ? "阻断" : "提醒") + "</span></div>";
}

function reviewStep() {
  const result = validateModel(state.model);
  state.validation = result;
  const p = getProcess(state);
  return "<div class='step-layout'><div class='step-main'><div class='section-title'><span class='section-index'>01</span><div><h3>发布前检查</h3><p>系统会把项目空间、数据标准、字段、粒度、维度关系和分层红线合并检查。</p></div><div class='score-ring " + (result.passed ? "ring-good" : "ring-warn") + "'><strong>" + result.score + "</strong><small>QUALITY</small></div></div><div class='validation-list'>" + join(result.checks.map(checkRow)) + "</div><div class='section-title section-title-spaced'><span class='section-index'>02</span><div><h3>模型摘要</h3><p>发布后，业务人员看到的是这份可解释的模型契约。</p></div></div><div class='summary-card'><div class='summary-row'><span>模型</span><strong>" + esc(state.model.name || "未命名模型") + "</strong><code>" + esc(state.model.code || "未填写") + "</code></div><div class='summary-row'><span>项目空间</span><strong>" + p.name + " / " + p.domain + "</strong><span class='layer-pill layer-" + layer(state.model.layer).color + "'>" + state.model.layer + " · " + layer(state.model.layer).label + "</span></div><div class='summary-row'><span>标准绑定</span><strong>" + (state.model.standardBindings || []).length + " 项</strong><span>类型 · 长度 · 空值 · 默认值</span></div><div class='summary-row'><span>模型结构</span><strong>" + type(state.model.modelType).label + "</strong><span>" + state.model.fields.length + " 字段 · " + state.model.relations.length + " 关联</span></div><div class='summary-row'><span>粒度</span><strong>" + esc(state.model.grainStatement || "未填写") + "</strong></div></div></div><aside class='step-aside'><div class='aside-card publish-card'><span class='publish-kicker'>READY TO PUBLISH?</span><h4>" + (result.passed ? "这张模型可以发布了" : "还有 " + result.blockers.length + " 项必须处理") + "</h4><p>" + (result.passed ? "发布后会生成 v1.0.0，并在项目空间模型列表中可追踪。" : "请先处理左侧标记为阻断的项目，发布按钮会自动解锁。") + "</p><button class='primary-button full' data-action='publish' " + (result.passed ? "" : "disabled") + ">" + icon("publish") + " 发布模型</button><button class='secondary-button full' data-action='save-draft'>" + icon("clock") + " 保存为草稿</button></div><div class='aside-card checklist-card'><div class='aside-heading'><span>" + icon("quality") + "</span><div><span class='panel-eyebrow'>POSTCONDITIONS</span><h4>发布后结果</h4></div></div><div class='postcondition'><span>" + icon("check") + "</span><span>模型版本 v1.0.0</span></div><div class='postcondition'><span>" + icon("check") + "</span><span>项目空间发布日志可追踪</span></div><div class='postcondition'><span>" + icon("check") + "</span><span>质量规则入口已准备</span></div></div></aside></div>";
}

function wizard() {
  const bodies = [contextStep, schemaStep, grainStep, relationStep, reviewStep];
  return "<main class='main-content'>" + topbar("新建模型", "MODEL CENTER / NEW MODEL") + "<section class='wizard-shell'>" + stepper() + header() + "<div class='wizard-body'>" + bodies[state.step]() + "</div><div class='wizard-footer'><button class='ghost-button' data-action='cancel-wizard'>取消</button><div class='wizard-footer-right'>" + (state.step > 0 ? "<button class='secondary-button' data-action='previous-step'>" + icon("back") + " 上一步</button>" : "") + (state.step < steps.length - 1 ? "<button class='primary-button' data-action='next-step'>下一步 " + icon("arrow") + "</button>" : "") + "</div></div></section></main>";
}

function published() {
  const result = state.publishResult || {};
  return "<main class='main-content'>" + topbar("发布完成", "MODEL CENTER / PUBLISH RESULT") + "<section class='published-shell'><div class='success-hero'><div class='success-mark'>" + icon("check") + "</div><span class='hero-kicker'>MODEL PUBLISHED</span><h2>" + esc(state.model.name) + "</h2><p>模型已完成发布，项目空间、粒度和维度关系已形成可追踪快照。</p><div class='published-tags'><span>" + state.model.layer + " · " + layer(state.model.layer).label + "</span><span>" + type(state.model.modelType).label + "</span><span>版本 " + (result.version || state.model.version) + "</span></div></div><div class='publish-grid'><div class='panel publish-summary'><div class='panel-heading'><div><span class='panel-eyebrow'>RELEASE SUMMARY</span><h3>发布结果</h3></div><span class='model-status status-published'>已发布</span></div><div class='release-kv'><span>模型编码</span><code>" + esc(result.modelCode || state.model.code) + "</code></div><div class='release-kv'><span>部署分层</span><strong>" + state.model.layer + " · " + layer(state.model.layer).label + "</strong></div><div class='release-kv'><span>项目空间</span><strong>" + getProcess(state).name + " · " + getProcess(state).domain + "</strong></div><div class='release-kv'><span>生成时间</span><strong>" + (result.generatedAt || "刚刚") + "</strong></div><div class='release-actions'><button class='primary-button' data-action='open-published-model'>查看模型详情 " + icon("arrow") + "</button><button class='secondary-button' data-action='new-model'>继续新建模型</button></div></div><div class='panel release-timeline'><div class='panel-heading'><div><span class='panel-eyebrow'>TRACEABLE LOG</span><h3>发布日志</h3></div><span class='status-dot live'>SUCCESS</span></div><div class='timeline'><div class='timeline-item done'><span>" + icon("check") + "</span><div><strong>发布前检查</strong><small>7 项检查完成 · 质量分 " + (state.validation ? state.validation.score : 96) + "</small></div><time>刚刚</time></div><div class='timeline-item done'><span>" + icon("check") + "</span><div><strong>生成模型版本</strong><small>" + (result.version || "v1.0.0") + " · 字段快照已固化</small></div><time>刚刚</time></div><div class='timeline-item done'><span>" + icon("check") + "</span><div><strong>写入模型目录</strong><small>已加入“" + getProcess(state).name + "”项目空间模型列表</small></div><time>刚刚</time></div><div class='timeline-item current'><span>" + icon("publish") + "</span><div><strong>后续可操作</strong><small>生成质量规则 · 导出 DDL · 发起版本对比</small></div><time>下一步</time></div></div></div></div><div class='panel next-actions'><div class='next-action-icon'>✦</div><div><span class='panel-eyebrow'>NEXT ACTIONS</span><h3>模型已经可被后续开发使用</h3><p>你可以继续配置质量规则，或基于这个版本创建下一个汇总模型。</p></div><button class='text-button' data-action='navigate' data-view='overview'>回到模型总览 " + icon("arrow") + "</button></div></section></main>";
}

function legacyPlaceholder(title, description) {
  const data = title === "一致性维度" ? MOCK_DIMENSIONS : MOCK_PROCESSES;
  return "<main class='main-content'>" + topbar(title, "MODEL CENTER / REGISTRY") + "<section class='placeholder-shell'><div class='placeholder-icon'>" + icon(title === "一致性维度" ? "dimension" : "process") + "</div><span class='hero-kicker'>MOCK REGISTRY</span><h2>" + title + "</h2><p>" + description + "</p><div class='placeholder-list'>" + join(data.map((item) => "<div><span>" + icon(title === "一致性维度" ? "dimension" : "process") + "</span><strong>" + item.name + "</strong><small>" + (item.domain || item.owner) + "</small></div>")) + "</div><button class='primary-button' data-action='new-model'>" + icon("plus") + " 从此处开始建模</button></section></main>";
}

function ledgerLink(label, href, linkLabel, action, attributes) {
  return "<a class='ledger-link' href='" + href + "' data-action='" + (action || "ledger-link") + "' data-link-label='" + esc(linkLabel || label) + "' " + (attributes || "") + ">" + label + " <span>→</span></a>";
}

function ledgerRow(entry) {
  const statusClass = entry.status === "published" ? "published" : "draft";
  return "<tr><td data-label='模型'><div class='ledger-model-name'><span class='ledger-model-mark'>" + (entry.modelType === "维度表" ? "◇" : entry.modelType === "汇总表" ? "▥" : "▦") + "</span><div><strong>" + esc(entry.name) + "</strong><code>" + esc(entry.code) + "</code></div></div></td><td data-label='项目空间'><strong>" + esc(entry.projectName) + "</strong><small>" + esc(entry.projectDomain) + "</small></td><td data-label='分层 / 类型'><span class='ledger-layer'>" + entry.layer + "</span><small>" + entry.modelType + "</small></td><td data-label='标准'><span class='ledger-standard " + (entry.standardStatus === "已登记" ? "ready" : "pending") + "'>" + entry.standardCount + "/" + MOCK_STANDARDS.length + " · " + entry.standardStatus + "</span></td><td data-label='粒度'><span class='ledger-grain'>" + esc(entry.grain) + "</span></td><td data-label='状态'><span class='ledger-status " + statusClass + "'>" + entry.statusLabel + "</span><small>" + esc(entry.updatedAt) + "</small></td><td data-label='链接'><div class='ledger-links'>" + ledgerLink("模型", entry.links.model, "查看模型详情", "open-model", "data-model-id='" + entry.id + "'") + ledgerLink("标准", entry.links.fields, "查看字段标准") + ledgerLink("关系", entry.links.relations, "查看关系快照") + "</div></td></tr>";
}

function legacyEmbeddedLedgerPage() {
  const activeProject = project(state.model.projectId);
  const entries = getLedgerEntries(state);
  const publishedCount = entries.filter((entry) => entry.status === "published").length;
  const draftCount = entries.filter((entry) => entry.status === "draft").length;
  const readyCount = entries.filter((entry) => entry.standardStatus === "已登记").length;
  return "<div class='dts-ledger-page'><header class='dts-shell-header'><nav class='dts-breadcrumb' aria-label='页面路径'><span>数据开发与运维</span><b>›</b><span>维度建模</span><b>›</b><strong>低代码开发向导</strong></nav><div class='dts-search'>搜索模块与页面 <kbd>Ctrl K</kbd></div></header><main class='dts-ledger-main'><section class='dts-page-head'><div><span class='dts-eyebrow'>DATA DEVELOPMENT / STEP 04</span><h1>数据开发 / 低代码开发向导</h1><p>建模登记作为向导中的治理入口：先确认项目空间，再通过链接进入专业模型页面。</p></div><div class='dts-head-actions'><button class='dts-button secondary' data-action='ledger-link' data-link-label='首张报表' href='#report/first'>▤ 首张报表</button><button class='dts-button primary' data-action='ledger-link' data-link-label='选择业务表' href='#asset/table'>▤ 选择业务表</button></div></section><section class='dts-banner'><span class='dts-banner-icon'>i</span><div><strong>从业务表到指标和报表数据集</strong><p>本页只登记项目空间、模型状态和治理链接；字段设计、粒度、关系与发布由专业页面承接。</p></div><a href='#flow' class='dts-banner-link' data-action='ledger-link' data-link-label='进入流程'>进入流程 ×</a></section><section class='dts-precondition'><div><strong>建模前置条件</strong><small>项目空间是业务过程边界，模型台账必须可追溯到项目与标准。</small></div><div class='dts-precondition-status'><span class='dts-chip warning'>数据源未接入</span><span>标准目录已就绪</span><span>项目空间已选择</span><a href='#asset/table' data-action='ledger-link' data-link-label='选择数据源'>选择数据源 →</a></div></section><section class='dts-summary-strip'><div><span class='summary-icon ready'>✓</span><div><strong>" + readyCount + "</strong><small>可直接推进节点</small></div></div><div><span class='summary-icon review'>▣</span><div><strong>" + draftCount + "</strong><small>需要工程审核节点</small></div></div><div><span class='summary-icon publish'>♢</span><div><strong>" + publishedCount + "</strong><small>已形成发布闭环</small></div></div></section><section class='dts-ledger-panel'><div class='dts-ledger-heading'><div><span class='dts-eyebrow'>MODEL LEDGER</span><h2>模型台账</h2><p>只在这里看归属、状态和入口，不在向导内重复建设专业编辑器。</p></div><label class='dts-project-filter'><span>当前项目空间</span><select data-field='projectId'>" + MOCK_PROJECT_SPACES.map((item) => "<option value='" + item.id + "'" + (item.id === activeProject.id ? " selected" : "") + ">" + esc(item.name) + " · " + esc(item.domain) + "</option>").join("") + "</select></label></div><div class='dts-ledger-table-wrap'><table class='dts-ledger-table'><thead><tr><th>模型</th><th>项目空间</th><th>分层 / 类型</th><th>标准</th><th>粒度声明</th><th>状态 / 更新时间</th><th>专业入口</th></tr></thead><tbody>" + (entries.length ? entries.map(ledgerRow).join("") : "<tr><td colspan='7' class='ledger-empty'>当前项目空间还没有模型登记，请先从业务表选择入口。</td></tr>") + "</tbody></table></div></section><section class='dts-link-panel'><div><span class='dts-eyebrow'>GOVERNANCE LINKS</span><h2>专业页面链接</h2><p>把复杂能力留给专业页面，向导只负责把用户送到正确位置。</p></div><div class='dts-link-grid'><a href='#standard-registry' data-action='ledger-link' data-link-label='数据标准登记'><strong>数据标准登记</strong><span>维护字段类型、长度、精度、非空和默认值。</span><em>进入标准目录 →</em></a><a href='#dimension-registry' data-action='ledger-link' data-link-label='一致性维度登记'><strong>一致性维度登记</strong><span>登记可复用维度，避免模型重复建设。</span><em>查看维度目录 →</em></a><a href='#model-detail' data-action='ledger-link' data-link-label='模型专业页'><strong>模型专业页</strong><span>完成字段、粒度、关系和发布门禁。</span><em>打开专业建模 →</em></a></div></section><footer class='dts-page-foot'><span>当前上下文：" + esc(activeProject.name) + " · " + esc(activeProject.domain) + " · 项目空间即业务过程</span><span>Mock 原型 · 数据不写入生产系统</span></footer></main></div>";
}

function ledgerTable(entries) {
  return "<div class='dts-ledger-table-wrap'><table class='dts-ledger-table'><thead><tr><th>模型</th><th>项目空间</th><th>分层 / 类型</th><th>标准</th><th>粒度声明</th><th>状态 / 更新时间</th><th>专业入口</th></tr></thead><tbody>" + (entries.length ? entries.map(ledgerRow).join("") : "<tr><td colspan='7' class='ledger-empty'>当前项目空间还没有模型登记，请从低代码向导或业务表入口开始。</td></tr>") + "</tbody></table></div>";
}

function modelLedgerPage() {
  const activeProject = project(state.model.projectId);
  const entries = getLedgerEntries(state);
  const publishedCount = entries.filter((entry) => entry.status === "published").length;
  const draftCount = entries.filter((entry) => entry.status === "draft").length;
  const readyCount = entries.filter((entry) => entry.standardStatus === "已登记").length;
  return "<div class='dts-ledger-page'><header class='dts-shell-header'><nav class='dts-breadcrumb' aria-label='页面路径'><span>数据开发与运维</span><b>›</b><span>数据建模</span><b>›</b><strong>模型台账</strong></nav><div class='dts-search'>搜索模块与页面 <kbd>Ctrl K</kbd></div></header><main class='dts-ledger-main'><section class='dts-page-head'><div><span class='dts-eyebrow'>DATA MODELING / MODEL LEDGER</span><h1>数据建模 / 模型台账</h1><p>独立的数据建模工作台。低代码向导只负责任务总览，具体建模工作从这里进入专业页面。</p></div><div class='dts-head-actions'><button class='dts-button secondary' data-action='open-wizard'>← 返回低代码向导</button><button class='dts-button primary' data-action='new-model'>＋ 新建模型</button></div></section><section class='dts-banner model-ledger-banner'><span class='dts-banner-icon'>⌘</span><div><strong>项目空间是业务过程，模型台账是独立建模入口</strong><p>先按项目空间定位模型，再从“模型 / 标准 / 关系”链接进入对应专业页面。</p></div><span class='dts-banner-meta'>MODEL LEDGER</span></section><section class='dts-precondition'><div><strong>当前建模上下文</strong><small>项目空间：" + esc(activeProject.name) + " · 主题域：" + esc(activeProject.domain) + " · 版本：" + activeProject.version + "</small></div><div class='dts-precondition-status'><span class='dts-chip ready'>标准目录已就绪</span><span>" + activeProject.ownerDept + " · " + activeProject.owner + "</span><a href='#project-spaces' data-action='ledger-link' data-link-label='切换项目空间'>切换项目空间 →</a></div></section><section class='dts-summary-strip'><div><span class='summary-icon ready'>✓</span><div><strong>" + readyCount + "</strong><small>标准已登记模型</small></div></div><div><span class='summary-icon review'>▣</span><div><strong>" + draftCount + "</strong><small>待继续完善模型</small></div></div><div><span class='summary-icon publish'>♢</span><div><strong>" + publishedCount + "</strong><small>已发布模型版本</small></div></div></section><section class='dts-ledger-panel'><div class='dts-ledger-heading'><div><span class='dts-eyebrow'>MODEL INVENTORY</span><h2>模型台账</h2><p>记录模型归属、标准准备度、粒度声明和专业页面入口。</p></div><label class='dts-project-filter'><span>当前项目空间</span><select data-field='projectId'>" + MOCK_PROJECT_SPACES.map((item) => "<option value='" + item.id + "'" + (item.id === activeProject.id ? " selected" : "") + ">" + esc(item.name) + " · " + esc(item.domain) + "</option>").join("") + "</select></label></div>" + ledgerTable(entries) + "</section><section class='dts-link-panel'><div><span class='dts-eyebrow'>SPECIALIST PAGES</span><h2>专业建模入口</h2><p>复杂能力独立承载，台账只负责定位与跳转。</p></div><div class='dts-link-grid'><a href='#standard-registry' data-action='ledger-link' data-link-label='数据标准登记'><strong>数据标准登记</strong><span>维护字段类型、长度、精度、非空和默认值。</span><em>进入标准目录 →</em></a><a href='#dimension-registry' data-action='ledger-link' data-link-label='一致性维度登记'><strong>一致性维度登记</strong><span>登记可复用维度，避免模型重复建设。</span><em>查看维度目录 →</em></a><a href='#model-detail' data-action='ledger-link' data-link-label='模型专业页'><strong>模型专业页</strong><span>完成字段、粒度、关系和发布门禁。</span><em>打开专业建模 →</em></a></div></section><footer class='dts-page-foot'><span>当前上下文：" + esc(activeProject.name) + " · " + esc(activeProject.domain) + " · 独立数据建模</span><span>Mock 原型 · 数据不写入生产系统</span></footer></main></div>";
}

function wizardTaskCard(task, index) {
  const tone = task.status === "ready" ? "ready" : task.status === "progress" ? "progress" : "blocked";
  const iconText = ["▤", "⌘", "◇", "▥"][index] || "•";
  const primaryTarget = task.id === "modeling" ? "open-ledger" : "wizard-task";
  return "<article class='wizard-task-card'><div class='wizard-task-head'><span class='wizard-task-index " + tone + "'>" + (index + 1) + "</span><span class='wizard-task-status " + tone + "'>" + task.statusLabel + "</span></div><div class='wizard-task-icon'>" + iconText + "</div><h3>" + task.title + "</h3><p>" + task.summary + "</p><div class='wizard-task-links'><a href='" + task.links.primary + "' data-action='" + primaryTarget + "' data-link-label='" + task.title + "'>" + (task.id === "modeling" ? "进入数据建模" : "处理此任务") + " <span>→</span></a><a href='" + task.links.secondary + "' data-action='wizard-task' data-link-label='" + task.title + "相关页面'>查看相关页面</a></div></article>";
}

function wizardOverviewPage() {
  const tasks = getWizardTasks(state);
  const ready = tasks.filter((task) => task.status === "ready" || task.status === "progress").length;
  const review = tasks.filter((task) => task.status === "blocked").length;
  return "<div class='dts-ledger-page wizard-overview-page'><header class='dts-shell-header'><nav class='dts-breadcrumb' aria-label='页面路径'><span>数据开发与运维</span><b>›</b><span>低代码开发</span><b>›</b><strong>低代码开发向导</strong></nav><div class='dts-search'>搜索模块与页面 <kbd>Ctrl K</kbd></div></header><main class='dts-ledger-main'><section class='dts-page-head'><div><span class='dts-eyebrow'>DATA DEVELOPMENT / WIZARD OVERVIEW</span><h1>数据开发 / 低代码开发向导</h1><p>这里是任务总览，不承载专业编辑。缺什么、补什么，从对应任务跳转到独立页面完成。</p></div><div class='dts-head-actions'><button class='dts-button secondary' data-action='ledger-link' data-link-label='首张报表' href='#report/first'>▤ 首张报表</button><button class='dts-button primary' data-action='open-ledger'>⌘ 进入数据建模</button></div></section><section class='dts-banner wizard-banner'><span class='dts-banner-icon'>i</span><div><strong>把数据准备、业务对象、数据建模和指标设计串成一条任务链</strong><p>向导只告诉客户下一步做什么；专业页面负责具体配置、校验和发布。</p></div><a href='#flow' class='dts-banner-link' data-action='ledger-link' data-link-label='查看完整流程'>查看完整流程 ×</a></section><section class='dts-precondition'><div><strong>向导前置条件</strong><small>当前流程仍有待处理任务，完成后才能形成完整的数据产品闭环。</small></div><div class='dts-precondition-status'><span class='dts-chip warning'>" + review + " 项待处理</span><span>" + ready + " 项可推进</span><a href='#asset/table' data-action='wizard-task' data-link-label='选择数据源'>选择数据源 →</a></div></section><section class='dts-summary-strip'><div><span class='summary-icon ready'>✓</span><div><strong>" + ready + "</strong><small>可直接推进节点</small></div></div><div><span class='summary-icon review'>▣</span><div><strong>" + review + "</strong><small>需要补齐的节点</small></div></div><div><span class='summary-icon publish'>♢</span><div><strong>1</strong><small>最终发布闭环</small></div></div></section><section class='wizard-task-section'><div class='dts-ledger-heading'><div><span class='dts-eyebrow'>TASK OVERVIEW</span><h2>任务总览</h2><p>按顺序完成任务；数据建模是独立页面，点击后进入模型台账。</p></div></div><div class='wizard-task-grid'>" + tasks.map(wizardTaskCard).join("") + "</div></section><footer class='dts-page-foot'><span>当前向导：数据开发产品流程 · 数据建模通过独立台账承接</span><span>Mock 原型 · 数据不写入生产系统</span></footer></main></div>";
}

function placeholder(title, description) {
  const isStandards = title === "数据标准";
  const data = isStandards ? MOCK_STANDARDS : title === "项目空间" ? MOCK_PROJECT_SPACES : MOCK_DIMENSIONS;
  const rows = data.map((item) => {
    const secondary = isStandards ? item.code + " · " + item.type + (item.length !== "-" ? "(" + item.length + ")" : "") : item.domain || item.owner;
    return "<div><span>" + icon(isStandards ? "standard" : title === "项目空间" ? "process" : "dimension") + "</span><strong>" + item.name + "</strong><small>" + secondary + "</small></div>";
  }).join("");
  return "<main class='main-content'>" + topbar(title, "MODEL CENTER / REGISTRY") + "<section class='placeholder-shell'><div class='placeholder-icon'>" + icon(isStandards ? "standard" : title === "项目空间" ? "process" : "dimension") + "</div><span class='hero-kicker'>MOCK REGISTRY</span><h2>" + title + "</h2><p>" + description + "</p><div class='placeholder-list'>" + rows + "</div><button class='primary-button' data-action='new-model'>" + icon("plus") + " 从此处开始建模</button></section></main>";
}

function render() {
  let page = state.view === "ledger" ? modelLedgerPage() : state.view === "wizard-overview" ? wizardOverviewPage() : overview();
  if (state.view === "wizard") page = wizard();
  if (state.view === "published") page = published();
  if (state.view === "dimensions") page = placeholder("一致性维度", "统一登记可复用维度，建模时优先引用已有语义。");
  if (state.view === "processes") page = placeholder("项目空间", "项目空间就是业务过程，先确定项目边界、主题域和责任人，再进入模型设计。");
  if (state.view === "standards") page = placeholder("数据标准", "数据标准为字段提供名称、类型、长度、精度、空值和默认值契约，是模型发布前的必备依据。");
  const lightView = state.view === "ledger" || state.view === "wizard-overview";
  root.className = lightView ? "ledger-mode" : "";
  root.innerHTML = (lightView ? page : "<div class='app-shell'>" + sidebar() + page + "</div>") + (state.toast ? "<div class='toast toast-" + state.toast.tone + "'><span>" + icon(state.toast.tone === "success" ? "check" : state.toast.tone === "warning" ? "warning" : "clock") + "</span>" + esc(state.toast.message) + "</div>" : "");
}

function nextStep() {
  const result = validateModel(state.model);
  const requiredByStep = [["context", "standards", "identity"], ["fields"], ["grain"], ["relations"], []][state.step];
  const check = result.checks.find((item) => requiredByStep.includes(item.id) && !item.passed);
  if (check) {
    toast(check.label + "还未满足，请先补充必要信息。", "warning");
    return;
  }
  state.step = Math.min(steps.length - 1, state.step + 1);
  render();
}

root.addEventListener("click", (event) => {
  const target = event.target.closest("[data-action]");
  if (!target) return;
  const action = target.dataset.action;
  if (action === "ledger-link") { event.preventDefault(); toast("已打开“" + (target.dataset.linkLabel || "专业页面") + "”入口（mock）。"); }
  else if (action === "open-wizard") { state.view = "wizard-overview"; render(); }
  else if (action === "open-ledger") { event.preventDefault(); state.view = "ledger"; render(); }
  else if (action === "wizard-task") { event.preventDefault(); toast("已打开“" + (target.dataset.linkLabel || "相关任务") + "”入口（mock）。"); }
  else if (action === "new-model") { resetDraft(state); hydrateDemoModel(state); render(); }
  else if (action === "navigate") { const view = target.dataset.view; if (view === "wizard") { resetDraft(state); hydrateDemoModel(state); } else state.view = view; render(); }
  else if (action === "next-step") nextStep();
  else if (action === "previous-step") { state.step = Math.max(0, state.step - 1); render(); }
  else if (action === "jump-step") { const step = Number(target.dataset.step); if (step <= state.step) { state.step = step; render(); } else toast("请按顺序完成前置步骤。"); }
  else if (action === "cancel-wizard") { state.view = "ledger"; render(); }
  else if (action === "add-field") { addField(state); render(); }
  else if (action === "remove-field") { removeField(state, target.dataset.fieldId); render(); }
  else if (action === "toggle-dimension") { toggleDimension(state, target.dataset.dimensionId); render(); }
  else if (action === "open-model") { const model = state.savedModels.find((item) => item.id === target.dataset.modelId); if (model) { state.model = Object.assign(state.model, structuredClone(model), { modelType: model.type, savedAt: model.updatedAt }); state.step = 4; state.view = "wizard"; render(); } }
  else if (action === "save-draft") { saveDraft(state); toast("草稿已保存，稍后可以继续完善。", "success"); }
  else if (action === "publish") { const result = publishModel(state); if (result.published) render(); else toast("还有 " + state.validation.blockers.length + " 项发布阻断，请先处理。", "warning"); }
  else if (action === "open-published-model") { state.view = "wizard"; state.step = 4; render(); }
  else if (action === "auto-fill") { state.model.fields.forEach((item) => { if (item.standard === "待绑定标准") item.standard = item.label; }); toast("已为字段补齐 mock 数据标准绑定。", "success"); }
  else if (action === "bind-standard") toast("已模拟打开标准绑定抽屉。");
  else if (action === "add-relation") toast("关系由上一步的维度复用自动生成。");
  else if (action === "help") toast("从“新建模型”开始，按步骤完成一次发布。");
  else if (action === "notifications") toast("暂无新的建模通知。");
});

root.addEventListener("input", (event) => {
  const target = event.target;
  if (target.matches("[data-field]")) state.model[target.dataset.field] = target.value;
  if (target.matches("[data-field-prop]")) { const row = target.closest("[data-field-id]"); const field = state.model.fields.find((item) => item.id === row.dataset.fieldId); if (field) field[target.dataset.fieldProp] = target.value; }
});

root.addEventListener("change", (event) => {
  const target = event.target;
  if (target.matches("[data-field]")) state.model[target.dataset.field] = target.value;
  if (target.matches("[data-field-prop]")) { const row = target.closest("[data-field-id]"); const field = state.model.fields.find((item) => item.id === row.dataset.fieldId); if (field) field[target.dataset.fieldProp] = target.value; }
  if (target.matches("[data-grain-key]")) { const key = target.dataset.grainKey; state.model.grainKeys = target.checked ? Array.from(new Set(state.model.grainKeys.concat(key))) : state.model.grainKeys.filter((item) => item !== key); }
  if (target.matches("select, [data-grain-key]")) render();
});

render();
